@file:Suppress("MaxLineLength") // 陸地マスクの各行は144列の固定幅データで、折り返すと対応が取れなくなる

package io.github.task320.earthstep.feature.map

/**
 * 正距円筒図法のドット世界地図(P5-4 / P6-3)。
 *
 * 144x72 ドット(経度・緯度とも2.5度きざみ)の陸地マスク。
 * `#` が陸、`.` が海。行0が北緯90度、行71が南緯90度、
 * 列0が西経180度、列143が東経177.5〜180度に対応する。
 *
 * 横方向はシームレスに繋がる(列143の右隣が列0)。周回のラップ処理はこれに依存している。
 */
object WorldMapDots {

    const val COLUMNS = 144
    const val ROWS = 72

    /** 赤道に対応する行。ここをトレイルが東へ進む(仕様5.1 の決定)。 */
    const val EQUATOR_ROW = 36

    val rows: List<String> = listOf(
        "................................................................................................................................................",
        "................................................................................................................................................",
        "................................................................................................................................................",
        "............................................................#...................................................................................",
        "....................................................###############.............................................................................",
        "............................................######################.....................................###########..............................",
        ".............................................#####################.....................##################################.......................",
        ".....##################.......................###################................#.#############################################................",
        ".....##########################.................#################...........##################################################################..",
        ".....####################################........#############....#........#####################################################################",
        ".....####################################.........##########..####.........#####################################################################",
        "......######################################........#####.......#.........###################################################################...",
        "......#.........##############################........#..................#################################################################......",
        ".................################################.....................#...###########################################################..##.......",
        "..................#################################.................####...#####################################################.......#........",
        "....................##############################..................####.######################################################.......#.........",
        ".....................#############################....................#######################################################...................",
        "......................###########################.....................######################################################....................",
        ".......................##########################....................######################################################.....#...............",
        ".......................#########################....................#####################################################......###..............",
        "........................######################.......................########........###################################......###...............",
        "........................#####################.........................######..........##################################.....####...............",
        ".........................###################..........................##########.....###################################...#####................",
        ".........................#################...........................###################################################........................",
        "..........................###############...........................###################################################.........................",
        "...........................##############..........................####################################################.........................",
        "............................#############.........................####################################################..........................",
        ".............................##########.#.........................#############################....###################..........................",
        "..............................########....#.......................############################......#####...#######.....#.......................",
        ".................................##..............................###########################........#####.....#####.....#.......................",
        "...................................##............................##########################.........####.......###......##......................",
        ".....................................##....#......................#########################..........##........###......##......................",
        ".......................................###########.................##########################.........#.........##......###.....................",
        "..........................................########.................#########################....................##....#...#.....................",
        ".........................................############...............#######################......................#....#####.....................",
        ".........................................#############.....................###############.......................#....#####.....................",
        "........................................##################.................##############.....................#.......####...#..................",
        "........................................##################.................#############........................#....#####..########............",
        ".........................................#################.................#############..........................#######.....####..............",
        ".........................................##################................#############.............................####.......#...............",
        "..........................................################..................############...#................................#####...............",
        "...........................................###############..................############...#..............................########..............",
        "...........................................##############...................###########....#.............................##########.............",
        "............................................#############...................###########...#............................############.............",
        "............................................############.....................#########....#..........................###############............",
        "............................................############......................########...##..........................################...........",
        "............................................###########........................#####.................................################...........",
        "............................................#########...........................###..................................###############............",
        "...........................................#########.............................#...................................###############............",
